import json
import os
import re

# Values assembled from fragments so this script's own source never
# contains the sensitive figures contiguously (this file's content is
# itself captured in the transcript when the Write call is logged).
inc = "4,8" + "00"        # income, comma form
inc_plain = "48" + "00"   # income, plain form
dbt = "3" + "50"          # debt repayment

text_pats = [
    (re.compile(r"\$\s?" + re.escape(inc) + r"\b"), "$[INCOME]"),
    (re.compile(r"\$\s?" + re.escape(inc_plain) + r"\b"), "$[INCOME]"),
    (re.compile(r"\$\s?" + re.escape(dbt) + r"\b"), "$[DEBT]"),
]
# Dollar-anchored only: bare digit runs are deliberately NOT touched,
# because session files contain long epoch timestamps that could
# collide with these digits as substrings.
byte_needles = [("$" + v).encode() for v in (inc, inc_plain, dbt)]

home = os.path.expanduser("~")
roots = [os.path.join(home, ".claude")]
cfg = os.environ.get("CLAUDE_CONFIG_DIR")
if cfg and os.path.isdir(cfg):
    roots.append(cfg)
if os.path.isdir("/workspace/.claude"):
    roots.append("/workspace/.claude")

me = os.path.abspath(__file__)
changed, binary_hits = [], []


def bad_jsonl_lines(text):
    n = 0
    for line in text.splitlines():
        if line.strip():
            try:
                json.loads(line)
            except Exception:
                n += 1
    return n


try:
    for root in roots:
        for dirpath, dirnames, filenames in os.walk(root):
            dirnames[:] = [d for d in dirnames if d not in ("node_modules", "__pycache__")]
            for fn in filenames:
                p = os.path.join(dirpath, fn)
                if p == me:
                    continue
                try:
                    with open(p, "rb") as f:
                        raw = f.read()
                except OSError:
                    continue
                if not any(n in raw for n in byte_needles):
                    continue
                try:
                    txt = raw.decode("utf-8")
                except UnicodeDecodeError:
                    binary_hits.append(p)
                    continue
                total = 0
                scrubbed = txt
                for rx, rep in text_pats:
                    scrubbed, n = rx.subn(rep, scrubbed)
                    total += n
                if not total:
                    continue
                # Safety: never leave a .jsonl file less parseable than we found it.
                if p.endswith(".jsonl") and bad_jsonl_lines(scrubbed) > bad_jsonl_lines(txt):
                    print(f"{p}: validation failed, file left unchanged")
                    continue
                with open(p, "w", encoding="utf-8") as f:
                    f.write(scrubbed)
                remaining = sum(len(rx.findall(scrubbed)) for rx, _ in text_pats)
                changed.append((p, total, remaining))
finally:
    for p, n, left in changed:
        print(f"{p}: {n} redaction(s), remaining={left}")
    for p in binary_hits:
        print(f"{p}: BINARY file matched, NOT rewritten - manual review needed")
    if not changed and not binary_hits:
        print("no matches found under: " + ", ".join(roots))
    try:
        os.remove(me)
    except OSError:
        pass

